      xls: "Excel (visi metai)", issuer: "Emitentas", instr: "Turima", dir: "Kryptis", eng: "Kreipimasis į emitentą", onlyEng: "Rodyti tik tuos, kur reikia dėmesio", search: "Ieškoti emitento",
